// app.js — Express application with security best practices applied

'use strict';

const express = require('express');
const helmet  = require('helmet');

const app = express();

// ─── 1. SECURITY HEADERS ────────────────────────────────────────────────────
// Sets X-Content-Type-Options, X-Frame-Options, HSTS, and more automatically.
app.use(helmet());

// ─── 2. REQUEST BODY PARSING WITH SIZE LIMIT ────────────────────────────────
// Prevents large-payload attacks on POST/PUT routes.
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: false, limit: '10kb' }));

// ─── 3. RATE LIMITING ───────────────────────────────────────────────────────
// Limits each IP to 100 requests per 15-minute window.
// Requires: npm install express-rate-limit
const rateLimit = require('express-rate-limit');
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,
  standardHeaders: true,  // Return rate limit info in RateLimit-* headers
  legacyHeaders: false,   // Disable X-RateLimit-* headers
  message: { error: 'Too many requests. Please try again later.' },
});
app.use(limiter);

// ─── 4. HEALTH CHECK ────────────────────────────────────────────────────────
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// ─── 5. USERS ENDPOINT WITH INPUT VALIDATION ────────────────────────────────
const VALID_USERS = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob',   email: 'bob@example.com'   },
];

app.get('/users', (req, res, next) => {
  try {
    const { id } = req.query;

    // If an optional ?id= filter is provided, validate it strictly.
    if (id !== undefined) {
      const parsed = parseInt(id, 10);

      // Reject non-integer or non-positive values.
      if (!Number.isInteger(parsed) || parsed <= 0 || String(parsed) !== id.trim()) {
        return res.status(400).json({ error: 'Invalid id parameter. Must be a positive integer.' });
      }

      const user = VALID_USERS.find((u) => u.id === parsed);
      if (!user) {
        return res.status(404).json({ error: 'User not found.' });
      }
      return res.json(user);
    }

    res.json(VALID_USERS);
  } catch (err) {
    next(err); // Forward unexpected errors to the global error handler
  }
});

// ─── 6. 404 HANDLER ─────────────────────────────────────────────────────────
// Catches all unmatched routes and returns a clean JSON response
// instead of Express's default HTML page (which leaks framework details).
app.use((req, res) => {
  res.status(404).json({ error: 'Route not found.' });
});

// ─── 7. GLOBAL ERROR HANDLER ────────────────────────────────────────────────
// Catches errors forwarded via next(err) from any route.
// Logs the full error internally but NEVER sends stack traces to the client.
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  // Use a structured logger (e.g. pino/winston) in production.
  console.error({
    message: err.message,
    stack:   err.stack,
    url:     req.originalUrl,
    method:  req.method,
    time:    new Date().toISOString(),
  });

  const status = err.status || err.statusCode || 500;

  // Only expose a generic message to the client.
  res.status(status).json({ error: 'An unexpected error occurred.' });
});

// ─── 8. SERVER STARTUP ──────────────────────────────────────────────────────
// Port sourced from the environment; falls back to 3000 for local development.
const PORT = parseInt(process.env.PORT || '3000', 10);

const server = app.listen(PORT, () => {
  // Use a logger with log levels (warn/info/error) in production.
  console.log(`[${new Date().toISOString()}] Server running on port ${PORT}`);
});

module.exports = { app, server }; // Export server too, for clean shutdown in tests

