'use strict';

// ------------------------------------------------------------
// Dependencies  (npm i express helmet express-rate-limit)
// ------------------------------------------------------------
const express = require('express');
const helmet  = require('helmet');
const rateLimit = require('express-rate-limit');

const app  = express();
const PORT = process.env.PORT || 3000;

// ------------------------------------------------------------
// 1. Security headers
//    Helmet sets a sensible collection of HTTP response headers
//    (X-Content-Type-Options, X-Frame-Options, HSTS, CSP, …)
// ------------------------------------------------------------
app.use(helmet());

// ------------------------------------------------------------
// 2. Body parsing with strict size limits
//    Prevents large-payload / body-bomb attacks.
// ------------------------------------------------------------
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: false, limit: '10kb' }));

// ------------------------------------------------------------
// 3. Global rate limiter
//    Protects every endpoint from brute-force / DoS traffic.
// ------------------------------------------------------------
const globalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,                  // requests per window per IP
  standardHeaders: true,     // Return rate-limit info in RateLimit-* headers
  legacyHeaders: false,
  message: { error: 'Too many requests. Please try again later.' },
});
app.use(globalLimiter);

// ------------------------------------------------------------
// 4. Input-validation helper
//    Lightweight; swap for `joi` / `zod` in larger projects.
// ------------------------------------------------------------

/**
 * Returns true when `value` is a safe, non-negative integer string.
 * Rejects empty strings, floats, negatives, and non-numeric input.
 */
function isPositiveIntegerString(value) {
  return /^\d+$/.test(value) && parseInt(value, 10) > 0;
}

// ------------------------------------------------------------
// Routes
// ------------------------------------------------------------

// GET /health  — no sensitive data, no auth required
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// GET /users  — returns paginated user list
//   Query params:
//     page  (positive integer, default 1)
//     limit (positive integer, 1–100, default 20)
app.get('/users', (req, res, next) => {
  try {
    const rawPage  = req.query.page  ?? '1';
    const rawLimit = req.query.limit ?? '20';

    // --- Validate page ---
    if (!isPositiveIntegerString(rawPage)) {
      return res.status(400).json({
        error: 'Invalid query parameter: "page" must be a positive integer.',
      });
    }

    // --- Validate limit ---
    if (!isPositiveIntegerString(rawLimit)) {
      return res.status(400).json({
        error: 'Invalid query parameter: "limit" must be a positive integer.',
      });
    }

    const page  = parseInt(rawPage,  10);
    const limit = Math.min(parseInt(rawLimit, 10), 100); // cap at 100

    // NOTE: Replace this static array with a real database query.
    // Parameterised queries / an ORM should be used to prevent SQL injection.
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob',   email: 'bob@example.com'   },
    ];

    const start      = (page - 1) * limit;
    const paginated  = allUsers.slice(start, start + limit);
    const totalPages = Math.ceil(allUsers.length / limit);

    return res.json({
      data: paginated,
      meta: {
        page,
        limit,
        totalItems: allUsers.length,
        totalPages,
      },
    });
  } catch (err) {
    next(err); // hand off to the centralised error handler below
  }
});

// ------------------------------------------------------------
// 5. 404 handler  — catches requests to undefined routes
// ------------------------------------------------------------
app.use((req, res) => {
  res.status(404).json({ error: 'Route not found.' });
});

// ------------------------------------------------------------
// 6. Centralised error handler
//    Express recognises a 4-argument middleware as an error handler.
//    Keeps error logic in one place and avoids leaking stack traces.
// ------------------------------------------------------------
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  // Log the full error server-side for observability / auditing.
  // Replace console.error with your structured logger (e.g. pino, winston).
  console.error({
    message: err.message,
    stack:   err.stack,
    url:     req.originalUrl,
    method:  req.method,
    ip:      req.ip,
  });

  // Never expose internal details to the client.
  const statusCode = err.status || err.statusCode || 500;
  res.status(statusCode).json({
    error: statusCode < 500 ? err.message : 'An internal server error occurred.',
  });
});

// ------------------------------------------------------------
// 7. Start server (only when run directly, not when imported)
// ------------------------------------------------------------
if (require.main === module) {
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

module.exports = app;

