const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');

const app = express();

// ---------------------------------------------------------------------------
// 1. Security headers (helmet sets X-Content-Type-Options, X-Frame-Options,
//    Content-Security-Policy, etc.)
// ---------------------------------------------------------------------------
app.use(helmet());

// ---------------------------------------------------------------------------
// 2. Body parsing with a hard size limit to prevent payload-flooding attacks
// ---------------------------------------------------------------------------
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: false, limit: '10kb' }));

// ---------------------------------------------------------------------------
// 3. Rate limiting — applied globally; tighten per-route as needed
// ---------------------------------------------------------------------------
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,                  // max requests per window per IP
  standardHeaders: true,     // return rate-limit info in RateLimit-* headers
  legacyHeaders: false,      // disable X-RateLimit-* headers
  message: { error: 'Too many requests, please try again later.' },
});
app.use(limiter);

// ---------------------------------------------------------------------------
// 4. Minimal request logging (replace with a proper logger like `pino` or
//    `winston` in production — never log request bodies that may contain PII)
// ---------------------------------------------------------------------------
app.use((req, _res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.path}`);
  next();
});

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

app.get('/health', (_req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// NOTE: In a real application, user data must come from an authenticated,
// authorised database query — never hardcoded. Emails and other PII should
// only be returned to requests with appropriate authorisation.
app.get('/users', (_req, res) => {
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];
  res.json(users);
});

// ---------------------------------------------------------------------------
// 5. 404 handler — catches all unmatched routes with a clean JSON response
//    instead of leaking Express internals via its default HTML error page
// ---------------------------------------------------------------------------
app.use((_req, res) => {
  res.status(404).json({ error: 'Resource not found.' });
});

// ---------------------------------------------------------------------------
// 6. Global error handler — must have exactly 4 parameters so Express
//    recognises it as an error-handling middleware
// ---------------------------------------------------------------------------
// eslint-disable-next-line no-unused-vars
app.use((err, _req, res, _next) => {
  // Log the full error server-side for diagnostics …
  console.error(`[ERROR] ${err.stack || err.message}`);

  // … but never send internal details to the client
  const status = typeof err.status === 'number' ? err.status : 500;
  res.status(status).json({ error: 'An unexpected error occurred.' });
});

// ---------------------------------------------------------------------------
// 7. Use PORT from environment so the app is deployable without code changes
// ---------------------------------------------------------------------------
const PORT = parseInt(process.env.PORT, 10) || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;

