'use strict';

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');

const app = express();

// ─── 1. SECURITY HEADERS ────────────────────────────────────────────────────
// Sets X-Content-Type-Options, X-Frame-Options, HSTS, and more automatically.
app.use(helmet());

// ─── 2. BODY PARSING WITH SIZE LIMIT ────────────────────────────────────────
// Prevents payload-based DoS attacks by capping request body size.
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: false, limit: '10kb' }));

// ─── 3. RATE LIMITING ───────────────────────────────────────────────────────
// Limits each IP to 100 requests per 15-minute window.
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,
  standardHeaders: true,  // Return rate-limit info in RateLimit-* headers
  legacyHeaders: false,   // Disable X-RateLimit-* headers
  message: { error: 'Too many requests, please try again later.' },
});
app.use(limiter);

// ─── 4. HEALTH ENDPOINT ─────────────────────────────────────────────────────
// Kept minimal to avoid leaking server internals.
app.get('/health', (req, res) => {
  res.status(200).json({ status: 'ok' });
});

// ─── 5. USERS ENDPOINT WITH INPUT VALIDATION ────────────────────────────────
const USERS = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob',   email: 'bob@example.com'   },
];

// Validates and sanitises an optional ?id= query parameter.
function parseUserId(raw) {
  if (raw === undefined) return null;           // Parameter not provided — OK
  const parsed = Number(raw);
  if (!Number.isInteger(parsed) || parsed <= 0) {
    const err = new Error('Invalid id: must be a positive integer.');
    err.status = 400;
    throw err;
  }
  return parsed;
}

app.get('/users', (req, res, next) => {
  try {
    const id = parseUserId(req.query.id);

    if (id !== null) {
      const user = USERS.find((u) => u.id === id);
      if (!user) {
        return res.status(404).json({ error: 'User not found.' });
      }
      return res.status(200).json(user);
    }

    return res.status(200).json(USERS);
  } catch (err) {
    next(err); // Forward validation errors to the global error handler
  }
});

// ─── 6. 404 HANDLER ─────────────────────────────────────────────────────────
// Catches all requests to undefined routes before they reach Express defaults.
app.use((req, res) => {
  res.status(404).json({ error: 'Route not found.' });
});

// ─── 7. GLOBAL ERROR HANDLER ────────────────────────────────────────────────
