// Ensures stack traces and internal details are never sent to the client.
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  const statusCode = err.status || 500;

  // Log the full error server-side only
  console.error(`[${new Date().toISOString()}] ${req.method} ${req.path} — ${err.message}`);

  // Return a sanitised message to the client
  res.status(statusCode).json({
    error: statusCode < 500 ? err.message : 'An internal server error occurred.',
  });
});

// ─── 8. SERVER STARTUP ──────────────────────────────────────────────────────
// Port is read from environment; falls back to 3000 only in development.
const PORT = process.env.PORT || 3000;

if (require.main === module) {
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

module.exports = app;

