// ──────────────────────────────────────────────
// Security Middleware
// ──────────────────────────────────────────────

// [FIX #1] Apply security-related HTTP headers (CSP, X-Frame-Options, etc.)
app.use(helmet());

// [FIX #4] Restrict cross-origin requests to known, trusted origins only.
// Replace the origin value with your actual client domain(s) in production.
const corsOptions = {
  origin: process.env.ALLOWED_ORIGIN || 'http://localhost:3000',
  methods: ['GET'],
  optionsSuccessStatus: 200,
};
app.use(cors(corsOptions));

// [FIX #2] Global rate limiter: max 100 requests per 15-minute window per IP.
// Tune windowMs / max based on your expected traffic patterns.
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,
  standardHeaders: true,  // Return rate-limit info in the `RateLimit-*` headers
  legacyHeaders: false,   // Disable the deprecated `X-RateLimit-*` headers
  message: { error: 'Too many requests. Please try again later.' },
});
app.use(limiter);

// Parse incoming JSON bodies (needed if POST/PUT routes are added later)
app.use(express.json());

// ──────────────────────────────────────────────
// Request Logging  [FIX #8]
// ──────────────────────────────────────────────

// Lightweight structured logger. Replace with winston/pino for production use.
app.use((req, _res, next) => {
  console.log(
    JSON.stringify({
      time: new Date().toISOString(),
      method: req.method,
      path: req.path,
      ip: req.ip,
    })
  );
  next();
});

// ──────────────────────────────────────────────
// Routes
// ──────────────────────────────────────────────

app.get('/health', (_req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// [FIX #3] Never expose PII (e.g. emails) in a public listing endpoint.
// Return only the minimum data callers actually need.
// Gate sensitive fields behind authentication middleware in a real application.
app.get('/users', (_req, res) => {
  const users = [
    { id: 1, name: 'Alice' },
    { id: 2, name: 'Bob' },
  ];
  res.json(users);
});

// ──────────────────────────────────────────────
// Error Handling  [FIX #5, #6]
// ──────────────────────────────────────────────

// [FIX #6] Catch-all for routes that don't exist — must come after all route definitions.
app.use((_req, res) => {
  res.status(404).json({ error: 'Resource not found.' });
});

// [FIX #5] Centralised error handler — must have exactly 4 parameters so Express
// recognises it as an error-handling middleware.
// eslint-disable-next-line no-unused-vars
app.use((err, _req, res, _next) => {
  // Avoid leaking internal stack traces or implementation details to clients.
  console.error(
    JSON.stringify({
      time: new Date().toISOString(),
      error: err.message,
      stack: err.stack,
    })
  );

  const statusCode = err.status || err.statusCode || 500;
  res.status(statusCode).json({
    error:
      process.env.NODE_ENV === 'production'
        ? 'An unexpected error occurred.' // [SECURITY] Generic message hides internals
        : err.message,                    // Detailed message only in non-prod environments
  });
});

// ──────────────────────────────────────────────
// Server Startup  [FIX #7, #9]
// ──────────────────────────────────────────────

// [FIX #7] Read port from environment so it can be configured per deployment.
const PORT = parseInt(process.env.PORT || '3000', 10);

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
});

// [FIX #9] Graceful shutdown: stop accepting new connections and let in-flight
// requests finish before the process exits (e.g. on a SIGTERM from a container
// orchestrator like Kubernetes).
const shutdown = (signal) => {
  console.log(`Received ${signal}. Shutting down gracefully...`);
  server.close(() => {
    console.log('All connections closed. Process exiting.');
    process.exit(0);
  });

  // Force exit if graceful shutdown takes longer than 10 seconds.
  setTimeout(() => {
    console.error('Forced shutdown after timeout.');
    process.exit(1);
  }, 10_000).unref();
};

process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT',  () => shutdown('SIGINT'));

module.exports = app;

