    const page  = parsePositiveInt(req.query.page,  1,   1, 1000);
    const limit = parsePositiveInt(req.query.limit, 20,  1,  100);

    if (page === null || limit === null) {
      return res.status(400).json({ error: 'Invalid pagination parameters.' });
    }

    // Static data shown here; swap for a parameterised DB query in production.
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob',   email: 'bob@example.com'   },
    ];

    const start = (page - 1) * limit;
    const users = allUsers.slice(start, start + limit);

    res.json({ page, limit, total: allUsers.length, data: users });
  } catch (err) {
    next(err); // Forward unexpected errors to the global error handler
  }
});

// ---------------------------------------------------------------------------
// 6. 404 handler — must be registered after all valid routes
