// 7. Global error handler — must have exactly four parameters so Express
//    recognises it as an error-handling middleware.
//    Logs the full error server-side; sends only a sanitised message to the
//    client so stack traces and internal details are never exposed.
// ---------------------------------------------------------------------------
// eslint-disable-next-line no-unused-vars
app.use((err, _req, res, _next) => {
